                //        vmovups  ymm0, ymmword ptr [rcx]
                //        vpor     ymm0, ymm0, ymmword ptr [rcx+0x20]
                //        vpor     ymm0, ymm0, ymmword ptr [rcx+0x40]
                //        vpor     ymm0, ymm0, ymmword ptr [rcx+0x60]
                //        vptest   ymm0, ymm0
                //        sete     al
                //        movzx    rax, al
                //
                // G_M000_IG03:                ;; offset=0x0021
                //        vzeroupper
